<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .hidden { display: none; }
        label { display: block; margin-top: 10px; }
        #confirmation { padding: 20px; background-color: #e0f7fa; border: 1px solid #4dd0e1; }
        a { color: #00695c; }
    </style>
</head>
<body>
    <h1>MapleSure SponsorConnect: Disability Claim Submission</h1>
    <form id="claim-form">
        <fieldset>
            <legend>Lookup Member</legend>
            <label for="policy-number">Policy Number:</label>
            <input type="text" id="policy-number" name="policy-number" required aria-label="Policy Number">

            <label for="member-id">Member ID:</label>
            <input type="text" id="member-id" name="member-id" required aria-label="Member ID">

            <button type="button" onclick="lookupMember()">Look up member</button>

            <div id="member-details" class="hidden">
                <h3>Member Details</h3>
                <p id="member-name"></p>
            </div>
        </fieldset>

        <fieldset>
            <legend>Claim Details</legend>
            <label for="last-day-worked">Last Day Worked:</label>
            <input type="date" id="last-day-worked" name="last-day-worked" required aria-label="Last Day Worked">

            <label for="first-day-absent">First Day Absent:</label>
            <input type="date" id="first-day-absent" name="first-day-absent" required aria-label="First Day Absent">

            <label for="nature-of-absence">Nature of Absence:</label>
            <select id="nature-of-absence" name="nature-of-absence" required aria-label="Nature of Absence">
                <option value="sickness">Sickness</option>
                <option value="injury">Injury</option>
                <option value="other">Other</option>
            </select>

            <label for="details">Details:</label>
            <textarea id="details" name="details" rows="4" aria-label="Details"></textarea>
        </fieldset>

        <fieldset>
            <legend>Documents</legend>
            <label for="documents">Upload Documents:</label>
            <input type="file" id="documents" name="documents" multiple aria-label="Upload Documents">
            <ul id="file-list"></ul>
        </fieldset>

        <button type="submit" aria-label="Submit Claim">Submit Claim</button>
    </form>

    <div id="confirmation" class="hidden">
        <h2>Claim Submitted</h2>
        <p>Your claim has been received.</p>
        <p>Reference Number: <span id="reference-number"></span></p>
    </div>

    <aside aria-live="polite" id="config-panel">
        <h2>Support Information</h2>
        <p>Service Line Hours: <span id="service-line-hours"></span></p>
        <p>Help Centre: <a href="#" id="help-centre-url" target="_blank" rel="noopener">Visit here</a></p>
    </aside>

    <footer>
        <p>MapleSure Insurance — fictional demo application</p>
    </footer>

    <script>
        // Mock data representative of member lookup.
        const mockMembers = {
            "12345": { name: "John Doe" },
            "67890": { name: "Jane Smith" }
        };

        const config = {
            serviceLineHours: "Mon-Fri: 09:00 - 17:00",
            helpCentreUrl: "https://advisor-help-centre.example.com"
        };

        // Function to update the support panel dynamically
        function updateConfigPanel() {
            const serviceLineHoursElem = document.getElementById('service-line-hours');
            const helpCentreUrlElem = document.getElementById('help-centre-url');
            serviceLineHoursElem.textContent = config.serviceLineHours;
            helpCentreUrlElem.href = config.helpCentreUrl;

            // Simulating dynamic update of config
            setTimeout(() => {
                config.serviceLineHours = "Mon-Fri: 08:00 - 18:00";
                config.helpCentreUrl = "https://updated-help-centre.example.com";
                serviceLineHoursElem.textContent = config.serviceLineHours;
                helpCentreUrlElem.href = config.helpCentreUrl;
            }, 5000); // Updates after 5 seconds for demonstration
        }

        document.addEventListener("DOMContentLoaded", function() {
            const documentsInput = document.getElementById('documents');
            const fileList = document.getElementById('file-list');

            documentsInput.addEventListener('change', function() {
                fileList.innerHTML = '';
                Array.from(documentsInput.files).forEach(file => {
                    const li = document.createElement('li');
                    li.textContent = file.name;
                    fileList.appendChild(li);
                });
            });

            document.getElementById('claim-form').addEventListener('submit', function(e) {
                e.preventDefault();
                this.classList.add('hidden');
                document.getElementById('confirmation').classList.remove('hidden');

                const referenceNumber = `MS-2026-08-${Math.floor(Math.random() * 10000)}`;
                document.getElementById('reference-number').textContent = referenceNumber;
            });

            updateConfigPanel();
        });

        function lookupMember() {
            const memberId = document.getElementById('member-id').value;
            const memberDetails = mockMembers[memberId];

            const detailsDiv = document.getElementById('member-details');
            const memberNameElement = document.getElementById('member-name');

            if (memberDetails) {
                memberNameElement.textContent = `Name: ${memberDetails.name}`;
                detailsDiv.classList.remove('hidden');
            } else {
                memberNameElement.textContent = 'Member not found';
                detailsDiv.classList.remove('hidden');
            }
        }
    </script>
</body>
</html>

